#!/usr/bin/env bash
# Generated by edgepoint. Do not edit — run `edgepoint sync` instead.
#
# Run once, on a fresh Ubuntu Lightsail instance, as the default `ubuntu` user:
#
#   curl -fsSL https://raw.githubusercontent.com/<org>/<repo>/main/deploy/provision.sh | bash
#
# Safe to run again — every step checks before acting.
set -euo pipefail

say() { printf '\n\033[1m==> %s\033[0m\n' "$1"; }

[ "$(id -u)" -eq 0 ] && { echo "Run this as the ubuntu user, not root." >&2; exit 1; }

say "Updating the system"
sudo apt-get update -qq
sudo DEBIAN_FRONTEND=noninteractive apt-get upgrade -y -qq

# 1 GB is enough to *run* this stack but leaves nothing spare. Without swap a
# brief spike — a migration, a backup, an image pull — gets something killed by
# the OOM reaper, and the casualty is usually Postgres.
say "Adding 2 GB of swap"
if [ ! -f /swapfile ]; then
  sudo fallocate -l 2G /swapfile
  sudo chmod 600 /swapfile
  sudo mkswap /swapfile >/dev/null
  sudo swapon /swapfile
  echo '/swapfile none swap sw 0 0' | sudo tee -a /etc/fstab >/dev/null
  # Prefer RAM, but use swap before killing something.
  echo 'vm.swappiness=10' | sudo tee /etc/sysctl.d/99-swap.conf >/dev/null
  sudo sysctl -q -p /etc/sysctl.d/99-swap.conf
else
  echo "swap already present"
fi

say "Installing Docker"
if ! command -v docker >/dev/null 2>&1; then
  curl -fsSL https://get.docker.com | sudo sh
  sudo usermod -aG docker "$USER"
else
  echo "docker already installed"
fi

say "Limiting log growth"
# Container logs will fill a 40 GB disk given a few months and no supervision.
sudo mkdir -p /etc/docker
echo '{"log-driver":"json-file","log-opts":{"max-size":"10m","max-file":"3"}}' |
  sudo tee /etc/docker/daemon.json >/dev/null
sudo systemctl restart docker || true

say "Setting up the application directory"
sudo mkdir -p /srv/app/backups
sudo chown -R "$USER":"$USER" /srv/app

say "Nightly database backup"
sudo tee /etc/cron.daily/app-db-backup >/dev/null <<'CRON'
#!/bin/sh
# Keeps 7 days locally. Lightsail's own snapshots are the off-machine copy.
cd /srv/app || exit 0
docker compose -f compose.prod.yaml exec -T db \
  pg_dump -U postgres app | gzip > "backups/app-$(date +%F).sql.gz"
find backups -name 'app-*.sql.gz' -mtime +7 -delete
CRON
sudo chmod +x /etc/cron.daily/app-db-backup

say "Unattended security updates"
sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq unattended-upgrades
sudo dpkg-reconfigure -f noninteractive unattended-upgrades

cat <<'DONE'

==> Server ready.

Still to do, in the Lightsail console:
  1. Networking → attach a static IP (otherwise the address changes on reboot)
  2. Networking → firewall: allow 80 and 443, leave 22 to your address only
  3. Snapshots → turn on automatic snapshots

Then, on this server, put your .env in /srv/app/ and let the deploy run.

You may need to log out and back in before docker works without sudo.

DONE
